spawn(process.execPath, [viteBin, "--host", "127.0.0.1", "--port", String(port), "--strictPort"], {
      cwd: uiDir,
      stdio: "inherit",
      env: {
        // `VITE_AOF_UI_MODE: "assets"` stood here and is RETIRED with the query selector it
        // fed (milestone 45 / ADR-002). It was a build-time constant, set only here and read
        // only by the pre-45 render root's ternary; keeping it would leave the route decision
        // with two inputs — a URL and a baked env var — which is the two-homes-for-one-fact
        // shape this milestone exists to remove. The address bar is the one input now, and
        // the editor is reached at `/config`.
        ...process.env,
        VITE_AOF_API_URL: apiUrl,
        BROWSER: "none"
      }
    })

spawnSync(item.argv[0], item.argv.slice(1), {
        stdio: "inherit",
        shell: process.platform === "win32",
        env: {
          ...process.env,
          ...(item.installEnvironment ?? SAFE_NPM_EXEC_ENV)
        }
      })

spawnSync("git", ["ls-remote", MARKETPLACE_GIT_URL, tagRef], {
    encoding: "utf8",
    shell: process.platform === "win32"
  })

spawn(item.argv[0], item.argv.slice(1), {
      stdio: "inherit",
      shell: process.platform === "win32",
      env: { ...process.env }
    })

spawnChild(program, args, {
        cwd: options.cwd,
        env: options.env,
        stdio: options.stdio,
        shell: options.shell,
      })

execFile(bin, args, { cwd: brief.worktreeCwd, windowsHide: true, timeout: options.timeoutMs ?? 10 * 60 * 1000 }, (error, stdout) => {
        // A non-zero exit or a spawn fault is a `failed` outcome (never an unhandled
        // rejection out of this seam) — the caller completes the run accordingly.
        if (error) {
          resolve({ outcome: "failed", failureReason: "agent_error" });
          return;
        }
        try {
          const parsed = JSON.parse(String(stdout ?? ""));
          const terminal = parsed.terminal_reason ?? parsed.stop_reason ?? null;
          const ok = terminal === "completed" || terminal === "end_turn";
          resolve(ok ? { outcome: "done" } : { outcome: "failed", failureReason: "agent_error" });
        } catch {
          resolve({ outcome: "failed", failureReason: "agent_error" });
        }
      })

execFile("git", args, { cwd, env, timeout: timeoutMs, windowsHide: true }, (error, stdout, stderr) =>
      settleExecFile(error, stdout, stderr, resolve, reject)
    )

execFile("tailscale", args, { timeout: timeoutMs, windowsHide: true }, (error, stdout, stderr) =>
      settleExecFile(error, stdout, stderr, resolve, reject)
    )

execFile(installPath, args, { timeout: timeoutMs, windowsHide: true }, (error, stdout, stderr) =>
      settleExecFile(error, stdout, stderr, resolve, reject)
    )

execFile("git", args, { cwd, timeout: 5000, windowsHide: true }, (error, stdout) => {
      resolve(error ? null : String(stdout ?? "").trim());
    })

execFile("git", args, { cwd, env, timeout: timeoutMs, windowsHide: true }, (error, stdout, stderr) => {
      if (error && (error.code === "ENOENT" || error.killed || error.signal)) {
        reject(error);
        return;
      }
      resolve({ stdout: String(stdout ?? ""), stderr: String(stderr ?? ""), status: error ? (typeof error.code === "number" ? error.code : 1) : 0 });
    })

execFile("git", args, { cwd, env, timeout: timeoutMs, windowsHide: true }, (error, stdout, stderr) => {
      if (error && (error.code === "ENOENT" || error.killed || error.signal)) {
        reject(error);
